func (c *Client) Sqlite3ColumnNameAsync(p_stmt Stmt, p_n int32) (Sqlite3ColumnNameFuture, error) {
	if err := c.c.CheckHandle(p_stmt.Handle, false); err != nil {
		return Sqlite3ColumnNameFuture{}, err
	}
	// G1: stmt u32 @0, n i32 @4; no variable group.
	// RESP_BOUND = G2pad 0 + ret 1036 (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpSqlite3ColumnName, 8, 1036)
	if err != nil {
		return Sqlite3ColumnNameFuture{}, err
	}
	body := e.Body()
	hqqLE.PutUint32(body[0:], p_stmt.ID())
	hqqLE.PutUint32(body[4:], uint32(p_n))
	call, err := c.c.Submit(e)
	if err != nil {
		return Sqlite3ColumnNameFuture{}, err
	}
	return Sqlite3ColumnNameFuture{c, call, call.ID()}, nil
}

func (f Sqlite3ColumnNameFuture) Wait() (*string, error) {
	if f.c == nil {
		return nil, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return nil, err
	}
	defer d.Release()
	b := d.Body
	// G2: none; V2: ret from 0.
	if d.Fail || d.Detail {
		return nil, d.Malformed()
	}
	off := 0
	off = rt.Align(off, 4)
	if off+4 > len(b) {
		return nil, d.Malformed()
	}
	var r *string
	if hqqLE.Uint32(b[off:]) == rt.NullLen {
		off += 4
	} else {
		var s string
		if s, off, err = rt.GetStr(b, off, 1024); err != nil {
			return nil, d.Malformed()
		}
		r = &s
	}
	if off != len(b) {
		return nil, d.Malformed()
	}
	return r, nil
}

