type StmtInfoFuture struct {
	c    *Client
	call *rt.Call
	id   uint32
}

// stmt_info(stmt)
//
// Results: (ret, error).
func (c *Client) StmtInfo(p_stmt Stmt) (StmtMeta, error) {
	f, err := c.StmtInfoAsync(p_stmt)
	if err != nil {
		return StmtMeta{}, err
	}
	return f.Wait()
}

func (c *Client) StmtInfoAsync(p_stmt Stmt) (StmtInfoFuture, error) {
	if err := c.c.CheckHandle(p_stmt.Handle, false); err != nil {
		return StmtInfoFuture{}, err
	}
	// G1: stmt u32 @0; no variable group.
	// RESP_BOUND = G2pad 0 + ret 1048576 (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpStmtInfo, 4, 1048576)
	if err != nil {
		return StmtInfoFuture{}, err
	}
	body := e.Body()
	hqqLE.PutUint32(body[0:], p_stmt.ID())
	call, err := c.c.Submit(e)
	if err != nil {
		return StmtInfoFuture{}, err
	}
	return StmtInfoFuture{c, call, call.ID()}, nil
}

func (f StmtInfoFuture) Wait() (StmtMeta, error) {
	if f.c == nil {
		return StmtMeta{}, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return StmtMeta{}, err
	}
	defer d.Release()
	b := d.Body
	// G2: none; V2: ret from 0.
	if d.Fail || d.Detail {
		return StmtMeta{}, d.Malformed()
	}
	off := 0
	var r StmtMeta
	off = rt.Align(off, 4)
	if off+4 > len(b) {
		return StmtMeta{}, d.Malformed()
	}
	r.Nparams = hqqLE.Uint32(b[off:])
	off += 4
	if off+1 > len(b) {
		return StmtMeta{}, d.Malformed()
	}
	if b[off] > 1 {
		return StmtMeta{}, d.Malformed()
	}
	r.Readonly = b[off] == 1
	off += 1
	cnt, off, err := rt.GetCount(b, off, 32766, 5) // str[]<=32766, minsize(str) = 5
	if err != nil {
		return StmtMeta{}, d.Malformed()
	}
	out := make([]string, 0, cnt)
	for i := uint32(0); i < cnt; i++ {
		var v string
		if v, off, err = rt.GetStr(b, off, 0); err != nil {
			return StmtMeta{}, d.Malformed()
		}
		out = append(out, v)
	}
	r.Param_names = out
	cnt1, off, err := rt.GetCount(b, off, 2000, 10) // Column[]<=2000, minsize(Column) = 10
	if err != nil {
		return StmtMeta{}, d.Malformed()
	}
	out1 := make([]Column, 0, cnt1)
	for i1 := uint32(0); i1 < cnt1; i1++ {
		var v1 Column
		if v1.Name, off, err = rt.GetStr(b, off, 1024); err != nil {
			return StmtMeta{}, d.Malformed()
		}
		if v1.Decltype, off, err = rt.GetStr(b, off, 1024); err != nil {
			return StmtMeta{}, d.Malformed()
		}
		out1 = append(out1, v1)
	}
	r.Columns = out1
	if off != len(b) {
		return StmtMeta{}, d.Malformed()
	}
	return r, nil
}

type FetchRowsFuture struct {
	c    *Client
	call *rt.Call
	id   uint32
}

// fetch_rows(stmt, max)
//
// Results: (ret, error).
func (c *Client) FetchRows(p_stmt Stmt, p_max int32) (Rows, error) {
	f, err := c.FetchRowsAsync(p_stmt, p_max)
	if err != nil {
		return Rows{}, err
	}
	return f.Wait()
}

func (c *Client) FetchRowsAsync(p_stmt Stmt, p_max int32) (FetchRowsFuture, error) {
	if err := c.c.CheckHandle(p_stmt.Handle, false); err != nil {
		return FetchRowsFuture{}, err
	}
	// G1: stmt u32 @0, max i32 @4; no variable group.
	// RESP_BOUND = G2pad 0 + ret 65536 (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpFetchRows, 8, 65536)
	if err != nil {
		return FetchRowsFuture{}, err
	}
	body := e.Body()
	hqqLE.PutUint32(body[0:], p_stmt.ID())
	hqqLE.PutUint32(body[4:], uint32(p_max))
	call, err := c.c.Submit(e)
	if err != nil {
		return FetchRowsFuture{}, err
	}
	return FetchRowsFuture{c, call, call.ID()}, nil
}

func (f FetchRowsFuture) Wait() (Rows, error) {
	if f.c == nil {
		return Rows{}, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return Rows{}, err
	}
	defer d.Release()
	b := d.Body
	// G2: none; V2: ret from 0.
	if d.Fail || d.Detail {
		return Rows{}, d.Malformed()
	}
	off := 0
	var r Rows
	off = rt.Align(off, 4)
	if off+4 > len(b) {
		return Rows{}, d.Malformed()
	}
	r.Rc = int32(hqqLE.Uint32(b[off:]))
	off += 4
	off = rt.Align(off, 4)
	if off+4 > len(b) {
		return Rows{}, d.Malformed()
	}
	r.Ncols = hqqLE.Uint32(b[off:])
	off += 4
	cnt, off, err := rt.GetCount(b, off, 0, 4) // Value[], minsize(Value) = 4
	if err != nil {
		return Rows{}, d.Malformed()
	}
	out := make([]Value, 0, cnt)
	for i := uint32(0); i < cnt; i++ {
		var v Value
		off = rt.Align(off, 4)
		if off+4 > len(b) {
			return Rows{}, d.Malformed()
		}
		v.Tag = ValueTag(hqqLE.Uint32(b[off:]))
		off += 4
		switch v.Tag {
		case ValueInt:
			off = rt.Align(off, 8)
			if off+8 > len(b) {
				return Rows{}, d.Malformed()
			}
			v.Int = int64(hqqLE.Uint64(b[off:]))
			off += 8
		case ValueFloat:
			off = rt.Align(off, 8)
			if off+8 > len(b) {
				return Rows{}, d.Malformed()
			}
			v.Float = math.Float64frombits(hqqLE.Uint64(b[off:]))
			off += 8
		case ValueText:
			if v.Text, off, err = rt.GetStr(b, off, 0); err != nil {
				return Rows{}, d.Malformed()
			}
		case ValueBlob:
			var cnt1 uint32
			cnt1, off, err = rt.GetCount(b, off, 0, 1)
			if err != nil {
				return Rows{}, d.Malformed()
			}
			r1 := append([]byte(nil), b[off:off+int(cnt1)]...)
			off += int(cnt1)
			v.Blob = r1
		case ValueNull:
		case ValueTextRaw:
			var cnt2 uint32
			cnt2, off, err = rt.GetCount(b, off, 0, 1)
			if err != nil {
				return Rows{}, d.Malformed()
			}
			r2 := append([]byte(nil), b[off:off+int(cnt2)]...)
			off += int(cnt2)
			v.TextRaw = r2
		case ValueBigText:
			off = rt.Align(off, 8)
			if off+8 > len(b) {
				return Rows{}, d.Malformed()
			}
			v.BigText = hqqLE.Uint64(b[off:])
			off += 8
		case ValueBigBlob:
			off = rt.Align(off, 8)
			if off+8 > len(b) {
				return Rows{}, d.Malformed()
			}
			v.BigBlob = hqqLE.Uint64(b[off:])
			off += 8
		default:
			return Rows{}, d.Malformed()
		}
		out = append(out, v)
	}
	r.Cells = out
	if r.Errmsg, off, err = rt.GetStr(b, off, 1024); err != nil {
		return Rows{}, d.Malformed()
	}
	if off != len(b) {
		return Rows{}, d.Malformed()
	}
	return r, nil
}

type ColumnChunkFuture struct {
	c    *Client
	call *rt.Call
	id   uint32
	dst  []byte
}

// column_chunk(stmt, col, offset, out dst, cap, out n)
//
// Results: (dst, error).
//
// @error(status, ok(0)): any other return value is a *rt.LibError carrying it as Code; Detail is the text of stmt_errmsg.
//
// p_dst is the output storage, its length is the capacity sent to the server, and the result is p_dst[:n]. The slices must stay untouched until Wait returns.
func (c *Client) ColumnChunk(p_stmt Stmt, p_col int32, p_offset uint64, p_dst []byte) ([]byte, error) {
	f, err := c.ColumnChunkAsync(p_stmt, p_col, p_offset, p_dst)
	if err != nil {
		return nil, err
	}
	return f.Wait()
}

func (c *Client) ColumnChunkAsync(p_stmt Stmt, p_col int32, p_offset uint64, p_dst []byte) (ColumnChunkFuture, error) {
	if err := c.c.CheckHandle(p_stmt.Handle, false); err != nil {
		return ColumnChunkFuture{}, err
	}
	if len(p_dst) > 1048576 { // dst: bytes<=1048576
		return ColumnChunkFuture{}, rt.ErrInvalidArg
	}
	// G1: stmt u32 @0, col i32 @4, offset u64 @8, dst.cap u32 @16; no variable group.
	// RESP_BOUND = max(G2pad 8 + VarSlack + cap of dst, G2pad + DETAIL_RESERVE) (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpColumnChunk, 20, max(8+rt.VarSlack+int64(len(p_dst)), 8+rt.DetailReserve))
	if err != nil {
		return ColumnChunkFuture{}, err
	}
	body := e.Body()
	hqqLE.PutUint32(body[0:], p_stmt.ID())
	hqqLE.PutUint32(body[4:], uint32(p_col))
	hqqLE.PutUint64(body[8:], p_offset)
	hqqLE.PutUint32(body[16:], uint32(len(p_dst)))
	call, err := c.c.Submit(e)
	if err != nil {
		return ColumnChunkFuture{}, err
	}
	return ColumnChunkFuture{c, call, call.ID(), p_dst}, nil
}

func (f ColumnChunkFuture) Wait() ([]byte, error) {
	if f.c == nil {
		return nil, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return nil, err
	}
	defer d.Release()
	b := d.Body
	// G2: ret i32 @0 (size 4); V2: dst from 8; a failure carries a detail string at 8.
	if len(b) < 4 {
		return nil, d.Malformed()
	}
	rc := int32(hqqLE.Uint32(b[0:]))
	if (rc == 0) == d.Fail { // ok(0) <=> not F_FAIL
		return nil, d.Malformed()
	}
	if d.Fail {
		return nil, d.LibError("column_chunk", int64(rc), 4)
	}
	if d.Detail {
		return nil, d.Malformed()
	}
	n, end, err := rt.GetBytesInto(f.dst, b, 8)
	if err != nil || end != len(b) {
		return nil, d.Malformed()
	}
	return f.dst[:n], nil
}
